#[allow(dead_code)]
mod common;
#[allow(unused_imports)]
use common::{distinct, equal, ordered};
use std::ops::{Add, Neg, Sub};
use timetuck::HardSoftScore;

#[test]
fn of() {
    assert_eq!(HardSoftScore::of_hard(-147), HardSoftScore::new(-147, 0));
    assert_eq!(HardSoftScore::of_soft(-258), HardSoftScore::new(0, -258));
}

#[test]
fn parse_score() {
    assert_eq!(
        "-147hard/-258soft".parse::<HardSoftScore>().unwrap(),
        HardSoftScore::new(-147, -258)
    );
    assert_eq!(
        "-147hard/*soft".parse::<HardSoftScore>().unwrap(),
        HardSoftScore::new(-147, i64::MIN)
    );
    assert_eq!(
        "-1structural/0hard/-258soft"
            .parse::<HardSoftScore>()
            .unwrap(),
        HardSoftScore::new(0, -258).with_structural(-1)
    );
}

#[test]
fn to_short_string() {
    assert_eq!(HardSoftScore::new(0, 0).to_short_string(), "0");
    assert_eq!(HardSoftScore::new(0, -258).to_short_string(), "-258soft");
    assert_eq!(HardSoftScore::new(-147, 0).to_short_string(), "-147hard");
    assert_eq!(
        HardSoftScore::new(-147, -258).to_short_string(),
        "-147hard/-258soft"
    );
    assert_eq!(
        HardSoftScore::new(-147, -258)
            .with_structural(-1)
            .to_short_string(),
        "-1structural/-147hard/-258soft"
    );
}

#[test]
fn test_to_string() {
    assert_eq!((HardSoftScore::new(0, -258)).to_string(), "0hard/-258soft");
    assert_eq!(
        (HardSoftScore::new(-147, -258)).to_string(),
        "-147hard/-258soft"
    );
    assert_eq!(
        (HardSoftScore::new(-147, -258).with_structural(-1)).to_string(),
        "-1structural/-147hard/-258soft"
    );
}

#[test]
fn parse_score_illegal_argument() {
    assert!("-147".parse::<HardSoftScore>().is_err());
    assert!("-1structural/0hard".parse::<HardSoftScore>().is_err());
}

#[test]
fn feasible() {
    assert!(!(HardSoftScore::new(-5, -300)).is_feasible());
    assert!(!(HardSoftScore::new(0, -300).with_structural(-1)).is_feasible());
    assert!((HardSoftScore::new(0, -300)).is_feasible());
    assert!((HardSoftScore::new(2, -300)).is_feasible());
}

#[test]
fn add() {
    assert_eq!(
        HardSoftScore::new(20, -20).add(HardSoftScore::new(-1, -300)),
        HardSoftScore::new(19, -320)
    );
}

#[test]
fn subtract() {
    assert_eq!(
        HardSoftScore::new(20, -20).sub(HardSoftScore::new(-1, -300)),
        HardSoftScore::new(21, 280)
    );
}

#[test]
fn multiply() {
    assert_eq!(
        HardSoftScore::new(5, -5).multiply(1.2),
        HardSoftScore::new(6, -6)
    );
    assert_eq!(
        HardSoftScore::new(1, -1).multiply(1.2),
        HardSoftScore::new(1, -2)
    );
    assert_eq!(
        HardSoftScore::new(4, -4).multiply(1.2),
        HardSoftScore::new(4, -5)
    );
}

#[test]
fn divide() {
    assert_eq!(
        HardSoftScore::new(25, -25).divide(5.0),
        HardSoftScore::new(5, -5)
    );
    assert_eq!(
        HardSoftScore::new(21, -21).divide(5.0),
        HardSoftScore::new(4, -5)
    );
    assert_eq!(
        HardSoftScore::new(24, -24).divide(5.0),
        HardSoftScore::new(4, -5)
    );
}

#[test]
fn power() {
    assert_eq!(
        HardSoftScore::new(-4, 5).power(2.0),
        HardSoftScore::new(16, 25)
    );
    assert_eq!(
        HardSoftScore::new(16, 25).power(0.5),
        HardSoftScore::new(4, 5)
    );
}

#[test]
fn negate() {
    assert_eq!(HardSoftScore::new(4, -5).neg(), HardSoftScore::new(-4, 5));
    assert_eq!(HardSoftScore::new(-4, 5).neg(), HardSoftScore::new(4, -5));
}

#[test]
fn abs() {
    assert_eq!(HardSoftScore::new(4, 5).abs(), HardSoftScore::new(4, 5));
    assert_eq!(HardSoftScore::new(4, -5).abs(), HardSoftScore::new(4, 5));
    assert_eq!(HardSoftScore::new(-4, 5).abs(), HardSoftScore::new(4, 5));
    assert_eq!(HardSoftScore::new(-4, -5).abs(), HardSoftScore::new(4, 5));
}

#[test]
fn zero() {
    assert_eq!(HardSoftScore::ZERO, HardSoftScore::new(0, 0));
    assert!(HardSoftScore::ZERO.is_zero());
    assert!(!HardSoftScore::new(0, 1).is_zero());
}

#[test]
fn equals_and_hash_code() {
    equal(&[HardSoftScore::new(-10, -200), HardSoftScore::new(-10, -200)]);
    equal(&[
        HardSoftScore::new(-10, -200).with_structural(-1),
        HardSoftScore::new(-10, -200).with_structural(-1),
    ]);
    distinct(&[
        HardSoftScore::new(-10, -200),
        HardSoftScore::new(-30, -200),
        HardSoftScore::new(-10, -400),
        HardSoftScore::new(-10, -200).with_structural(-1),
    ]);
}

#[test]
fn compare_to() {
    ordered(&[
        HardSoftScore::new(-20, i64::MIN).with_structural(-1),
        HardSoftScore::new(-20, i64::MIN),
        HardSoftScore::new(-20, -20),
        HardSoftScore::new(-1, -300),
        HardSoftScore::new(-1, 4000),
        HardSoftScore::new(0, -1),
        HardSoftScore::new(0, 0),
        HardSoftScore::new(0, 1),
    ]);
}
